import React, { useState, useContext } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { AuthContext } from "../contexts/AuthContext";

export default function Login() {
  const navigate = useNavigate();
  const { login } = useContext(AuthContext);

  const [form, setForm] = useState({ email: "", password: "" });
  const [totp, setTotp] = useState("");
  const [step, setStep] = useState(1); // 1 = email+password, 2 = OTP
  const [userId, setUserId] = useState(null);
  const [message, setMessage] = useState("");

  const handleChange = (e) =>
    setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");

    try {
      if (step === 1) {
        // Step 1: email + password
        const res = await axios.post("http://localhost:4000/api/auth/login", form);

        if (res.data.requireTotp) {
          // OTP required → move to step 2
          setStep(2);
          setUserId(res.data.userId);
          setMessage("Please enter the 6-digit OTP from your Authenticator app.");
          return;
        }

        // Otherwise login success (admins/comelec etc.)
        finishLogin(res.data);

      } else if (step === 2) {
        // Step 2: OTP verification
        const res = await axios.post("http://localhost:4000/api/auth/login/verify", {
          userId,
          totp,
        });

        finishLogin(res.data);
      }
    } catch (err) {
      setMessage(err.response?.data?.error || "Login failed");
    }
  };

  const finishLogin = (data) => {
    const { token, user } = data;
    if (!token || !user) {
      setMessage("Invalid response from server");
      return;
    }

    login({ token, user });

    if (user.role === "admin") navigate("/admin-dashboard");
    else if (user.role === "comelec") navigate("/comelec-dashboard");
    else navigate("/student-dashboard");
  };

  return (
    <div style={{ display: "flex", justifyContent: "center", padding: "50px", fontFamily: "Arial, sans-serif" }}>
      <div style={{ width: "400px", padding: "30px", border: "1px solid #ddd", borderRadius: "10px", boxShadow: "0 4px 10px rgba(0,0,0,0.1)" }}>
        <h2 style={{ textAlign: "center", marginBottom: "20px", color: "#333" }}>
          {step === 1 ? "Login" : "Verify OTP"}
        </h2>

        <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {step === 1 ? (
            <>
              <input type="email" name="email" placeholder="Email" value={form.email} onChange={handleChange} required style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }} />
              <input type="password" name="password" placeholder="Password" value={form.password} onChange={handleChange} required style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }} />
              <button type="submit" style={{ padding: "12px", borderRadius: "5px", border: "none", backgroundColor: "#007bff", color: "#fff", fontWeight: "bold", cursor: "pointer" }}>
                Login
              </button>
            </>
          ) : (
            <>
              <input type="text" placeholder="Enter 6-digit OTP" value={totp} onChange={(e) => setTotp(e.target.value)} required style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }} />
              <button type="submit" style={{ padding: "12px", borderRadius: "5px", border: "none", backgroundColor: "#28a745", color: "#fff", fontWeight: "bold", cursor: "pointer" }}>
                Verify OTP
              </button>
            </>
          )}
        </form>

        {message && <p style={{ marginTop: "20px", textAlign: "center", color: "red" }}>{message}</p>}

        {step === 1 && (
          <p style={{ marginTop: "20px", textAlign: "center", color: "#555" }}>
            Don't have an account?{" "}
            <button
              type="button"
              style={{ color: "#007bff", fontWeight: "bold", cursor: "pointer", background: "none", border: "none", padding: 0 }}
              onClick={() => navigate("/register")}
            >
              Register
            </button>
          </p>
        )}
      </div>
    </div>
  );
}
